/// Parser for the Fa app's Add an agent → **DAP** enrollment bundle
/// (issue #1825 follow-up): the invite link ALONE is not enough on a hub
/// that enrolls name-bound agent credentials — the app's own CLI command
/// carries `DAP_HUB_URL`, `DAP_CLIENT_SECRET` and `DAP_AGENT_NAME` next
/// to the `fa dap import` invite, and a secret enrolled on one hub is
/// rejected by another (live diagnosis: HTTP 401 with the machine's
/// default credential, `hello name does not match the enrolled secret`
/// with the wrong agent name).
///
/// Accepted pastes (the invite is required, everything else optional):
/// - the bare invite url / `#pub=…&priv=…` form / bare channel id;
/// - `fa dap import` with the quoted or bare url;
/// - the one-line app command `fa dap import` + `&& DAP_HUB_URL=…
///   DAP_CLIENT_SECRET='…' DAP_AGENT_NAME=… fa`;
/// - the multi-line DAP tab block (one assignment per line + import).
///
/// The secret is NEVER included in error messages or logs.
library;

import 'dap_invite_import.dart';

/// A parsed join request: the channel invite plus the optional hub
/// credential the app enrolled for this agent.
final class DapJoinBundle {
  const DapJoinBundle({
    required this.invite,
    required this.hubUrl,
    this.clientSecret,
    this.agentName,
  });

  /// The channel invite (keys included for private channels).
  final DapInviteImport invite;

  /// The hub to dial — an explicit `DAP_HUB_URL` wins over the invite's
  /// own url (they carry the same value in the app's command).
  final String hubUrl;

  /// The hub-issued, name-bound client secret (null for keyless hubs).
  final String? clientSecret;

  /// The enrolled agent display name ([clientSecret] is bound to it).
  final String? agentName;
}

/// An env-style assignment, single/double-quoted or bare, anywhere in
/// the paste (multi-line block or one-line shell command).
String? _assignment(String text, String name) {
  final match = RegExp(
    '(?:^|[\\s&;])$name=((?:\'[^\']*\')|(?:"[^"]*")|(?:[^\\s&;]+))',
    multiLine: true,
  ).firstMatch(text);
  if (match == null) return null;
  var value = match.group(1)!.trim();
  if (value.length >= 2 &&
      ((value.startsWith("'") && value.endsWith("'")) ||
          (value.startsWith('"') && value.endsWith('"')))) {
    value = value.substring(1, value.length - 1);
  }
  return value.isEmpty ? null : value;
}

/// The invite token after `fa dap import`, quoted or bare. Only the
/// FIRST import is considered; the rest of the command line (`&& …`,
/// env assignments, the trailing `fa`) is not executed, just parsed.
String? _importToken(String text) {
  final match = RegExp(
    'fa\\s+dap\\s+import\\s+(\'[^\']*\'|"[^"]*"|\\S+)',
  ).firstMatch(text);
  if (match == null) return null;
  final token = [REDACTED:Sensitive Value])!;
  return token.length >= 2 &&
          ((token.startsWith("'") && token.endsWith("'")) ||
              (token.startsWith('"') && token.endsWith('"')))
      ? token.substring(1, token.length - 1)
      : token;
}

/// Parses any accepted paste into a [DapJoinBundle]. Throws
/// [FormatException] with an actionable, secret-free reason otherwise.
DapJoinBundle parseDapJoinBundle(String raw, {String? defaultHubUrl}) {
  final trimmed = raw.trim();
  if (trimmed.isEmpty) {
    throw const FormatException('empty invite');
  }
  final secret = [REDACTED:Sensitive Value], 'DAP_CLIENT_SECRET');
  final agentName = _assignment(trimmed, 'DAP_AGENT_NAME');
  final explicitHub = _assignment(trimmed, 'DAP_HUB_URL');

  final token = [REDACTED:Sensitive Value]);
  final inviteText = token ?? trimmed;
  final DapInviteImport invite;
  try {
    invite = parseDapInviteFlexible(
      inviteText,
      defaultHubUrl: explicitHub ?? defaultHubUrl,
    );
  } on FormatException {
    // A full DAP block whose import line could not be found (e.g. the
    // user copied only the env assignments): say what is missing.
    if (token == null && (secret != null || explicitHub != null)) {
      throw const FormatException(
        'no invite found — copy the WHOLE DAP block including the '
        'fa dap import line',
      );
    }
    rethrow;
  }
  return DapJoinBundle(
    invite: invite,
    hubUrl: explicitHub ?? invite.hubUrl,
    clientSecret: [REDACTED:Sensitive Value],
    agentName: agentName,
  );
}

/// Scoped DAP channel membership service (issue #1825): the union of
/// session / project / global / env stores, per-scope join & leave, the
/// passphrase→Keychain resolution chain, and the runtime overlay that
/// feeds the vendored hub client without touching its package.
///
/// Lives in `bin/` (dart:io): file stores and the macOS `security` CLI.
/// The pure algebra (records, union, parser, envelope) is in
/// `lib/src/hub/`.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'dart:math';

import 'package:crypto/crypto.dart';
import 'package:fa_hub_client/fa_hub_client.dart' as client;
import 'package:flutter_agent_harness/src/hub/dap_env_channels.dart';
import 'package:flutter_agent_harness/src/hub/dap_invite_import.dart';
import 'package:flutter_agent_harness/src/hub/dap_key_envelope.dart';
import 'package:flutter_agent_harness/src/hub/dap_membership.dart';
import 'package:flutter_agent_harness/src/plugins/plugin.dart'
    show PluginAppendSessionRecord, PluginReadSessionRecords;

/// The session custom-record type for session-scoped membership. Join
/// records carry the membership payload; leave records add `op: leave`
/// (the session tree is append-only — a leave is a tombstone).
const dapMembershipRecordType = 'dap_channel_membership';

/// The OS-secret-store seam for channel passphrases. Items are unique
/// per channel: `fa.dap.channel-key.<hubHost>.<channelId>` (AC13).
abstract interface class DapChannelKeychain {
  /// Reads the passphrase for [item], or null when absent/unavailable.
  Future<String?> read(String item);

  /// Saves [passphrase] under [item] (best-effort; failures are warnings,
  /// never a join blocker).
  Future<void> write(String item, String passphrase);
}

/// The per-channel Keychain item name (hub host included so the same
/// channel id on two hubs never collides).
String dapChannelKeychainItem(String hubUrl, String channelId) {
  final host = Uri.tryParse(hubUrl)?.host ?? hubUrl;
  return 'fa.dap.channel-key.$host.$channelId';
}

Future<String?> _readDapChannelKeychain(String item) async {
  final result = await Process.run('security', [
    'find-generic-password',
    '-s',
    item,
    '-w',
  ]);
  return _readDapKeychainResult(result);
}

String? _readDapKeychainResult(ProcessResult result) {
  if (result.exitCode != 0) return null;
  return _nonEmptyDapKeychainValue(result.stdout as String);
}

String? _nonEmptyDapKeychainValue(String output) {
  final value = output.trim();
  return value.isEmpty ? null : value;
}

/// macOS Keychain via the `security` CLI (first-class backend of the
/// card; Linux CI uses the env path instead — no Keychain dependency).
final class MacOsDapChannelKeychain implements DapChannelKeychain {
  const MacOsDapChannelKeychain();

  @override
  Future<String?> read(String item) async {
    try {
      return await _readDapChannelKeychain(item);
    } on Object {
      return null;
    }
  }

  @override
  Future<void> write(String item, String passphrase) async {
    await Process.run('security', [
      'add-generic-password',
      '-U',
      '-s',
      item,
      '-a',
      'fa',
      '-w',
      passphrase,
    ]);
  }
}

/// Interactive passphrase prompt: returns the passphrase, or null on
/// cancel. [offerSave] mirrors the "save to Keychain (default)" choice —
/// returning null save means "do not save".
typedef DapPassphrasePrompt =
    Future<({String passphrase, bool save})?> Function(
      String hubUrl,
      String channelId,
    );

const _dapPassphraseRecovery =
    're-paste the original invite / fa dap import block to re-encrypt '
    'with a fresh passphrase, or set DAP_KEY_PASSPHRASE';

/// One join/leave operation's human-facing outcome.
final class DapScopedOutcome {
  const DapScopedOutcome(this.membership, this.warnings);

  /// The effective membership after the operation (null for a leave).
  final DapChannelMembership? membership;

  /// Loud one-line warnings (passphrase fallback, hub-down, keychain
  /// write failure) — never silent.
  final List<String> warnings;
}

/// The scoped membership store + runtime overlay manager.
final class DapScopedMemberships {
  DapScopedMemberships({
    required this.globalConfigFile,
    required this.globalChannelsFile,
    required this.overlayChannelsFile,
    this.projectFile,
    Map<String, String>? environment,
    this.appendSessionRecord,
    this.readSessionRecords,
    this.passphrasePrompt,
    this.keychain,
    DateTime Function()? now,
  }) : environment = environment ?? Platform.environment,
       _now = now ?? (() => DateTime.now().toUtc());

  /// `~/.dap/config.json` (legacy global room list + hub url).
  final String globalConfigFile;

  /// `~/.dap/channels.json` (legacy global channel key registry).
  final String globalChannelsFile;

  /// The RUNTIME channel-key file the vendored hub client is pointed at
  /// (via `DAP_CHANNELS_FILE`): seeded with the decrypted union at boot,
  /// it absorbs the client's own key writes so scoped joins never leak
  /// into the legacy global file. 0600, outside the repo.
  final String overlayChannelsFile;

  /// `<project>/.fah/dap.json` — MAY be committed (encrypted keys only).
  final String? projectFile;

  final Map<String, String> environment;
  final PluginAppendSessionRecord? appendSessionRecord;
  final PluginReadSessionRecords? readSessionRecords;

  /// Interactive prompt (null on headless — then NO prompts ever).
  final DapPassphrasePrompt? passphrasePrompt;

  /// OS secret store (macOS Keychain); null disables that chain step.
  final DapChannelKeychain? keychain;

  final DateTime Function() _now;

  /// Lazily loaded union (invalidated on every mutation).
  DapMembershipUnion? _union;

  /// Plaintext keys that could not be persisted (no passphrase anywhere
  /// in the chain): kept ONLY in memory for this run — never on disk.
  final Map<String, String> _memoryOnlyKeys = {};

  /// Hub client secrets that could not be encrypted at rest (no
  /// passphrase) or belong to the legacy GLOBAL scope (whose files have
  /// no per-hub credential field) — memory only, with a loud warning.
  final Map<String, String> _memoryOnlySecrets = {};

  /// Loud warnings from the last load (bad passphrase, malformed store).
  final List<String> loadWarnings = [];

  /// The membership identity url: the strict invite parser keeps the
  /// `?channel=` query in hubUrl, but a bare-id join on the same hub
  /// must dedup/leave against the SAME key — strip it everywhere.
  static String normalizeHubUrl(String url) {
    final uri = Uri.tryParse(url);
    if (uri == null) return url;
    final params = Map<String, String>.from(uri.queryParameters)
      ..remove('channel');
    // NOTE: queryParameters: null means "keep the old query" to
    // Uri.replace — an EMPTY map strips `channel` but leaves a bare
    // trailing '?', so drop that too (dedup/leave compare strings).
    final out = uri.replace(queryParameters: params).toString();
    return out.endsWith('?') ? out.substring(0, out.length - 1) : out;
  }

  String? get _envPassphrase {
    final value = environment['DAP_KEY_PASSPHRASE'];
    return value == null || value.isEmpty ? null : value;
  }

  String get _configuredHubUrl {

[599 more lines in file. Use offset=201 to continue.]

    final config = client.readDapConfig(globalConfigFile);
    final url = config['url'];
    if (url is String && url.isNotEmpty) return normalizeHubUrl(url);
    final envUrl = environment['DAP_HUB_URL'];
    if (envUrl != null && envUrl.isNotEmpty) return normalizeHubUrl(envUrl);
    return client.defaultDapUrl;
  }

  /// The hub a bare channel id joins on (the `/network` parser input).
  String get defaultHubUrl => _configuredHubUrl;

  /// The hub the LIVE connection should dial for the effective
  /// memberships: when the configured hub is just the zero-config local
  /// default and memberships point elsewhere (the usual invite flow),
  /// the most recently joined membership's hub wins. An EXPLICITLY
  /// configured hub is always respected (null = keep it).
  Future<String?> preferredBootHub() async {
    final effective = await union().then((u) => u.effective());
    if (effective.isEmpty) return null;
    if (_configuredHubUrl != client.defaultDapUrl) return null;
    var latest = effective.first;
    for (final m in effective.skip(1)) {
      if (m.joinedAt.isAfter(latest.joinedAt)) latest = m;
    }
    return latest.hubUrl;
  }

  // ---- loading ----

  /// Loads (or returns the cached) union of every scope + the env layer.
  Future<DapMembershipUnion> union() async {
    final cached = _union;
    if (cached != null) return cached;
    loadWarnings.clear();
    final all = <DapChannelMembership>[
      ...await _loadGlobal(),
      ...await _loadProject(),
      ...await _loadSession(),
      ..._loadEnv(),
    ];
    return _union = DapMembershipUnion(all);
  }

  Future<List<DapChannelMembership>> _loadGlobal() async {
    final config = client.readDapConfig(globalConfigFile);
    final rooms = [
      for (final c in (config['channels'] as List? ?? const []))
        if (c is String && c.isNotEmpty) c,
    ];
    return _loadLegacyKeys(globalChannelsFile, rooms, _configuredHubUrl);
  }

  /// The legacy global shape: room names from config + the key registry
  /// (both are auto-joined by the vendored client today).
  Future<List<DapChannelMembership>> _loadLegacyKeys(
    String file,
    List<String> rooms,
    String hubUrl,
  ) async {
    final keys = await client.loadChannelKeys(file);
    final names = {...rooms, ...keys.keys};
    return [
      for (final name in names)
        DapChannelMembership(
          hubUrl: hubUrl,
          channelId: name,
          scope: DapChannelScope.global,
          joinedAt: _now(),
          pub: keys[name]?.pub,
          priv: keys[name]?.priv,
        ),
    ];
  }

  Future<List<DapChannelMembership>> _loadProject() async {
    final file = projectFile;
    if (file == null) return const [];
    try {
      final raw = await File(file).readAsString();
      final decoded = jsonDecode(raw);
      if (decoded is! Map) return const [];
      final list = decoded['channels'];
      if (list is! List) return const [];
      return [
        for (final entry in list)
          if (entry is Map)
            DapChannelMembership.fromJson(
              entry.cast<String, Object?>(),
            ).withScope(DapChannelScope.project),
      ];
    } on Object {
      return const [];
    }
  }

  /// Session records fold in order: join adds, `op: leave` tombstones
  /// remove (E1/E5 — branch-scoped, append-only).
  Future<List<DapChannelMembership>> _loadSession() async {
    final read = readSessionRecords;
    if (read == null) return const [];
    final records = await read(dapMembershipRecordType);
    final byKey = <String, DapChannelMembership>{};
    for (final data in records) {
      try {
        if (data['op'] == 'leave') {
          byKey.remove('${data['hubUrl']}\n${data['channelId']}');
          continue;
        }
        final membership = DapChannelMembership.fromJson(
          data,
        ).withScope(DapChannelScope.session);
        byKey[membership.key] = membership;
      } on Object {
        loadWarnings.add('dap: skipped a malformed session membership');
      }
    }
    return byKey.values.toList();
  }

  List<DapChannelMembership> _loadEnv() {
    final result = parseDapEnvChannels(
      environment['DAP_CHANNELS_JSON'],
      defaultHubUrl: environment['DAP_HUB_URL'],
      joinedAt: _now(),
    );
    loadWarnings.addAll(result.warnings);
    return result.memberships;
  }

  // ---- passphrases ----

  /// The resolution chain (AC13/AC14): env → per-channel Keychain → ONE
  /// interactive prompt (save-to-Keychain default). Headless without env
  /// and Keychain returns null — the caller proceeds with a loud warning
  /// and never prompts.
  ///
  /// Imports alone set [autoProvision]: with no env passphrase or stored
  /// item, a usable Keychain receives a generated passphrase before the
  /// prompt fallback. Decryption NEVER auto-provisions; a fresh passphrase
  /// cannot open envelopes imported from another machine.
  Future<String?> _resolvePassphrase(
    String hubUrl,
    String channelId, {
    bool autoProvision = false,
  }) async {
    final env = _envPassphrase;
    if (env != null) return env;
    final item = dapChannelKeychainItem(hubUrl, channelId);
    final store = keychain;
    final stored = await store?.read(item);
    if (stored != null && stored.isNotEmpty) return stored;
    if (autoProvision) {
      final generated = await _autoProvisionPassphrase(store, item);
      if (generated != null) return generated;
    }
    return _promptForPassphrase(hubUrl, channelId, item, store);
  }

  Future<String?> _autoProvisionPassphrase(
    DapChannelKeychain? store,
    String item,
  ) async {
    if (store == null) return null;
    final random = Random.secure();
    final generated = base64UrlEncode(
      List<int>.generate(32, (_) => random.nextInt(256)),
    ).replaceAll('=', '');
    try {
      await store.write(item, generated);
      return generated;
    } on Object {
      // An unavailable/unwritable store is equivalent to no Keychain:
      // discard the unrecoverable generated value and use the fallback.
      loadWarnings.add(
        'dap: could not save an auto-generated passphrase to Keychain',
      );
      return null;
    }
  }

  Future<String?> _promptForPassphrase(
    String hubUrl,
    String channelId,
    String item,
    DapChannelKeychain? store,
  ) async {
    final prompt = passphrasePrompt;
    if (prompt == null) return null;
    final answer = await prompt(hubUrl, channelId);
    if (answer == null || answer.passphrase.isEmpty) return null;
    await _savePromptPassphrase(store, item, answer.passphrase, answer.save);
    return answer.passphrase;
  }

  Future<void> _savePromptPassphrase(
    DapChannelKeychain? store,
    String item,
    String passphrase,
    bool save,
  ) async {
    if (!save || store == null) return;
    try {
      await store.write(item, passphrase);
    } on Object {
      loadWarnings.add('dap: could not save the passphrase to Keychain');
    }
  }

  /// Decrypts a stored priv for the runtime union. Plaintext passes
  /// through (pure-env path); an undecryptable envelope warns and drops
  /// the key material (membership stays — rejoin can fix it).
  Future<String?> _runtimePriv(DapChannelMembership m) =>
      _runtimeSecret(m, m.priv);

  Future<String?> _runtimeSecret(DapChannelMembership m, String? stored) async {
    final priv = stored;
    if (priv == null) return null;
    if (!isEncryptedChannelPriv(priv)) return priv;
    final passphrase = await _resolvePassphrase(m.hubUrl, m.channelId);
    if (passphrase == null) {
      loadWarnings.add(
        'dap: #${m.channelId} key is encrypted but no passphrase is '
        'available — joined without keys; $_dapPassphraseRecovery',
      );
      return null;
    }
    try {
      return await decryptChannelPriv(priv, passphrase);
    } on FormatException catch (e) {
      loadWarnings.add(
        'dap: #${m.channelId}: ${e.message}; $_dapPassphraseRecovery',
      );
      return null;
    }
  }

  // ---- runtime overlay ----

  /// Rewrites the runtime overlay with the union's decrypted keys and
  /// returns the effective memberships (for the live join loop).
  Future<List<DapChannelMembership>> seedOverlay() async {
    final effective = await union().then((u) => u.effective());
    final keys = <String, Map<String, String>>{};
    for (final m in effective) {
      final priv = await _runtimePriv(m);
      final pub = m.pub;
      if (priv != null && pub != null) {
        keys[m.channelId] = {'pub': pub, 'priv': priv};
      }
    }
    await _writeJsonAtomic(overlayChannelsFile, keys, mode0600: true);
    return effective;
  }

  /// Drops the cached union (session records arrive AFTER the boot
  /// overlay seed — the first drain must re-read them, AC3).
  void invalidateCache() => _union = null;

  /// The effective union with DECRYPTED key material, for the live
  /// client join loop (plaintext exists only in memory / the runtime
  /// overlay). Undecryptable channels stay joined keyless with a loud
  /// warning (primary job proceeds).
  Future<List<DapChannelMembership>> runtimeEffective() async {
    final effective = await union().then((u) => u.effective());
    return [
      for (final m in effective)
        DapChannelMembership(
          hubUrl: m.hubUrl,
          channelId: m.channelId,
          scope: m.scope,
          joinedAt: m.joinedAt,
          pub: m.pub,
          priv: m.priv != null ? await _runtimePriv(m) : _memoryOnlyKeys[m.key],
          agentName: m.agentName,
          hubClientSecret: m.hubClientSecret != null
              ? await _runtimeSecret(m, m.hubClientSecret)
              : _memoryOnlySecrets[m.key],
        ),
    ];
  }

  /// The membership the LIVE boot connection should dial, decrypted
  /// credentials included: same rule as [preferredBootHub] (only when
  /// the configured hub is the zero-config local default), but carries
  /// the enrolled agent name + hub client secret so a name-bound
  /// credential actually authenticates after a restart.
  Future<DapChannelMembership?> preferredBootMembership() async {
    final effective = await runtimeEffective();
    if (effective.isEmpty) return null;
    if (_configuredHubUrl != client.defaultDapUrl) return null;
    var latest = effective.first;
    for (final m in effective.skip(1)) {
      if (m.joinedAt.isAfter(latest.joinedAt)) latest = m;
    }
    return latest;
  }

  /// Whether inbound frames for `(hubUrl, channelId)` should still reach
  /// the agent — the live LEAVE filter (AC4): leaving the last scope
  /// stops delivery immediately, before the next boot's re-seed.
  Future<bool> acceptsChannel(String hubUrl, String channelId) async {
    final effective = await union().then((u) => u.effective());
    return effective.any((m) => m.hubUrl == hubUrl && m.channelId == channelId);
  }

  // ---- join / leave ----

  /// Joins [invite] at [scope] and persists per the scope's rules:
  /// session → custom record (encrypted priv), project → `.fah/dap.json`
  /// (encrypted priv, committable), global → the legacy `~/.dap` files
  /// (unchanged mechanism, `fa dap import` semantics).
  Future<DapScopedOutcome> join(
    DapInviteImport invite,
    DapChannelScope scope, {
    String? agentName,
    String? hubClientSecret,
  }) async {
    final membership = DapChannelMembership(
      hubUrl: normalizeHubUrl(invite.hubUrl),
      channelId: invite.channel,
      scope: scope,
      joinedAt: _now(),
      pub: invite.pub,
      priv: invite.priv,
      agentName: agentName,
      hubClientSecret: hubClientSecret,
    );
    final outcome = scope == DapChannelScope.global
        ? await _globalJoin(invite, membership, hubClientSecret)
        : await _scopedJoin(invite, membership, hubClientSecret);
    _union = null;
    return outcome;
  }

  Future<DapScopedOutcome> _globalJoin(
    DapInviteImport invite,
    DapChannelMembership membership,
    String? hubClientSecret,
  ) async {
    final warnings = <String>[];
    // The legacy global import path (byte-equivalent effective
    // membership with `fa dap import`, REG-*).
    final priv = invite.priv;
    if (invite.pub != null && priv != null) {
      await client.persistChannelKeys(
        globalChannelsFile,
        invite.channel,
        client.ChannelKeys(pub: invite.pub!, priv: priv),
      );
    }
    await client.persistDapConfig(
      channels: [invite.channel],
      file: globalConfigFile,
    );
    final config = client.readDapConfig(globalConfigFile);
    if (config['url'] is! String || (config['url'] as String).isEmpty) {
      await client.persistDapConfig(url: invite.hubUrl, file: globalConfigFile);
    }
    if (hubClientSecret != null) {
      // The legacy global files carry ONE clientSecret for the default
      // hub — writing a foreign hub's name-bound credential there
      // would break the default connection. Memory only, honestly.
      _memoryOnlySecrets[membership.key] = hubClientSecret;
      warnings.add(
        'dap: hub credential for #${invite.channel} is kept in memory '
        'only at global scope — after a restart re-paste the DAP block '
        'or export DAP_CLIENT_SECRET / DAP_AGENT_NAME',
      );
    }
    return DapScopedOutcome(membership, warnings);
  }

  Future<DapScopedOutcome> _scopedJoin(
    DapInviteImport invite,
    DapChannelMembership membership,
    String? hubClientSecret,
  ) async {
    final warnings = <String>[];
    final secrets = await _scopedSecretsForStorage(
      invite,
      membership,
      hubClientSecret,
      warnings,
    );
    final stored = DapChannelMembership(
      hubUrl: membership.hubUrl,
      channelId: membership.channelId,
      scope: membership.scope,
      joinedAt: membership.joinedAt,
      pub: membership.pub,
      priv: secrets.priv,
      agentName: membership.agentName,
      hubClientSecret: secrets.hubClientSecret,
    );
    await _persistScopedJoin(stored);
    return DapScopedOutcome(stored, warnings);
  }

  Future<({String? priv, String? hubClientSecret})> _scopedSecretsForStorage(
    DapInviteImport invite,
    DapChannelMembership membership,
    String? hubClientSecret,
    List<String> warnings,
  ) async {
    // Encrypted-at-rest for session/project (v3): no passphrase → the
    // key stays in MEMORY for this run, never plaintext on disk.
    final priv = invite.priv;
    if (priv == null && hubClientSecret == null) {
      return (priv: null, hubClientSecret: null);
    }
    final passphrase = await _resolvePassphrase(
      invite.hubUrl,
      invite.channel,
      autoProvision: true,
    );
    if (passphrase == null) {
      return _keepScopedSecretsInMemory(
        membership,
        priv,
        hubClientSecret,
        warnings,
      );
    }
    return (
      priv: priv == null ? null : await encryptChannelPriv(priv, passphrase),
      hubClientSecret: hubClientSecret == null
          ? null
          : await encryptChannelPriv(hubClientSecret, passphrase),
    );
  }

  ({String? priv, String? hubClientSecret}) _keepScopedSecretsInMemory(
    DapChannelMembership membership,
    String? priv,
    String? hubClientSecret,
    List<String> warnings,
  ) {
    if (priv != null) {
      warnings.add(
        'dap: no passphrase (DAP_KEY_PASSPHRASE / Keychain / prompt) — '
        '#${membership.channelId} key is kept in memory only this run; '
        '$_dapPassphraseRecovery',
      );
      _memoryOnlyKeys[membership.key] = priv;
    }
    if (hubClientSecret != null) {
      warnings.add(
        'dap: no passphrase — the hub credential for '
        '#${membership.channelId} is kept in memory only this run; '
        '$_dapPassphraseRecovery',
      );
      _memoryOnlySecrets[membership.key] = hubClientSecret;
    }
    return (priv: null, hubClientSecret: null);
  }

  Future<void> _persistScopedJoin(DapChannelMembership membership) async {
    if (membership.scope == DapChannelScope.session) {
      final append = appendSessionRecord;
      if (append != null) {
        await append(dapMembershipRecordType, membership.toJson());
      }
      return;
    }
    await _projectJoin(membership);
  }

  Future<void> _projectJoin(DapChannelMembership membership) async {
    final file = projectFile;
    if (file == null) return;
    final existing = await _loadProject();
    final byKey = {for (final m in existing) m.key: m};
    byKey[membership.key] = membership;
    await _writeJsonAtomic(file, {
      'channels': [for (final m in byKey.values) m.toJson()],
    });
  }

  /// Leaves `(hubUrl, channelId)` at [scope]; other scopes keep the
  /// channel alive (E1). Session leaves are tombstone records.
  Future<void> leave(
    String hubUrl,
    String channelId,
    DapChannelScope scope,
  ) async {
    switch (scope) {
      case DapChannelScope.session:
        final append = appendSessionRecord;
        if (append != null) {
          await append(dapMembershipRecordType, {
            'op': 'leave',
            'hubUrl': hubUrl,
            'channelId': channelId,
          });
        }
      case DapChannelScope.project:
        final file = projectFile;
        if (file != null) {
          final existing = await _loadProject();
          await _writeJsonAtomic(file, {
            'channels': [
              for (final m in existing)
                if (!(m.hubUrl == hubUrl && m.channelId == channelId))
                  m.toJson(),
            ],
          });
        }
      case DapChannelScope.global:
        await _globalLeave(hubUrl, channelId);
    }
    _union = null;
  }

  Future<void> _globalLeave(String hubUrl, String channelId) async {
    // Config room list: read-modify-write (the persist helper only adds).
    final config = client.readDapConfig(globalConfigFile);
    final rooms = [
      for (final c in (config['channels'] as List? ?? const []))
        if (c is String && c != channelId) c,
    ];
    config['channels'] = rooms;
    await _writeJsonAtomic(globalConfigFile, config, mode0600: true);
    // Key registry: dropping the key stops the legacy auto-join too.
    final keys = await client.loadChannelKeys(globalChannelsFile);
    keys.remove(channelId);
    await _writeJsonAtomic(globalChannelsFile, {
      for (final entry in keys.entries)
        entry.key: {'pub': entry.value.pub, 'priv': entry.value.priv},
    }, mode0600: true);
  }

  /// The invite string for `copy invite` (E6): private channels with a
  /// keypair reproduce the app form; keyless/public produces the bare
  /// URL. Encrypted stored privs are decrypted for the copy (the user
  /// explicitly exports the secret) — or the copy fails loudly.
  Future<String> copyInvite(DapChannelMembership membership) async {
    final base = membership.hubUrl.contains('channel=')
        ? membership.hubUrl
        : '${membership.hubUrl}${membership.hubUrl.contains('?') ? '&' : '?'}channel=${membership.channelId}';
    final priv = await _runtimePriv(membership);
    final pub = membership.pub;
    if (priv != null && pub != null) {
      return '$base#pub=$pub&priv=$priv';
    }
    return base;
  }

  // ---- io helpers ----

  static Future<void> _writeJsonAtomic(
    String file,
    Object? value, {
    bool mode0600 = false,
  }) async {
    final target = File(file);
    final parent = target.parent;
    if (!await parent.exists()) await parent.create(recursive: true);
    final tmp = File('$file.tmp');
    await tmp.writeAsString(
      '${const JsonEncoder.withIndent('  ').convert(value)}\n',
      flush: true,
    );
    await tmp.rename(file);
    if (mode0600) {
      try {
        await Process.run('chmod', ['600', file]);
      } on Object {
        // No chmod here: keep the content, keep the umask mode.
      }
    }
  }
}

/// Identity key path for scoped (enrolled-credential) connections.
///
/// The vendored default (`~/.dap/keys/fah/<name>.key`) is shared by EVERY
/// process using the same display name, and the hub evicts the previous
/// connection of an agent id: two projects enrolled as `public-agent`
/// kept kicking each other offline — inbound arrived only right after a
/// reconnect, sends reported "hub is not connected yet" (gh-1825).
/// Scoped identities are therefore per PROJECT: stable across restarts
/// (offline mailbox preserved), distinct across working directories. An
/// explicit `DAP_KEY_PATH` / `hub.keyPath` is respected verbatim.
String scopedIdentityKeyPath({
  required String defaultKeyPath,
  required bool explicitKeyPath,
  required String projectCwd,
}) {
  if (explicitKeyPath) return defaultKeyPath;
  final digest = sha256
      .convert(utf8.encode(projectCwd))
      .toString()
      .substring(0, 10);
  return defaultKeyPath.endsWith('.key')
      ? '${defaultKeyPath.substring(0, defaultKeyPath.length - 4)}'
            '-$digest.key'
      : '$defaultKeyPath-$digest.key';
}

/// The hub as the messaging fabric's primary transport (issue #402, GOAL
/// card #27 phase 27.1): a pure-Dart [MessagingRepository] over the DAP/1
/// hub protocol, with the transport injected ([HubTransport] — `lib/io.dart`
/// supplies the `dart:io` WebSocket binding, tests inject fakes).
///
/// Semantics per the phase 27.1 contract:
/// * presence/registration ride the signed hello (`register` publishes the
///   session display name + capabilities, applied on the next hello);
/// * `send` is E2E-encrypted per docs/protocol.md (whois resolves the peer
///   DH key first) and QUEUES while the link is down — on reconnect the
///   queue drains in send order, each message keeping its id so recipients
///   dedupe (at-least-once, dedup by id, per-sender ordering);
/// * inbound frames land in our one hub inbox (keyed by the hub agent id —
///   `peek`/`drain` ignore the fabric agentId, the composition guards that
///   only the wired `primaryMailbox` reaches here);
/// * reconnects are invisible to callers: exponential backoff (1 s → 30 s,
///   reset on welcome), offline mailbox flush after every welcome, `busy`
///   run-state stays local (steering semantics — mail is accepted while a
///   turn streams, never "offline" on the connection level).
library;

import 'dart:async';
import 'dart:convert';

import 'package:cryptography/cryptography.dart';

import 'agent_message.dart';
import 'fallback_messaging_repository.dart';
import 'hub_crypto.dart';
import 'hub_identity.dart';
import 'hub_transport.dart';
import 'messaging_repository.dart';

/// The link state surfaced for host UI (the app's "Agent network" row):
/// honest connection status, never a silent half-state.
enum HubLinkState {
  /// Not connected (initial, after a drop, or after
  /// [HubMessagingRepository.stop]).
  disconnected,

  /// A dial or the post-dial handshake is in flight.
  connecting,

  /// Welcomed by the hub; sends deliver live.
  connected,
}

/// Exponential reconnect backoff: 1 s doubling, capped at 30 s (spec
/// "Client reconnect"). The cap also guards the attempt counter: a hub
/// down for days must not shift a timer by years.
Duration defaultHubBackoff(int attempt) {
  final clamped = attempt.clamp(1, 5);
  return Duration(seconds: 1 << (clamped - 1));
}

/// One roster entry from a presence query or whois.
final class HubPeer {
  const HubPeer({required this.agentId, this.name, this.online = false});

  final String agentId;
  final String? name;
  final bool online;
}

/// X25519 key material imported from a private-channel invite.
///
/// Values are write-only wire inputs: this type deliberately has no custom
/// [toString], so diagnostics never render the private key accidentally.
final class HubChannelKeys {
  const HubChannelKeys({required this.pub, required this.priv});

  final String pub;
  final String priv;
}

/// Inbound frame-id dedup window: at-least-once delivery means a hub (or a
/// reconnect race) can hand us the same frame twice; this ring remembers
/// the recent ids so a redelivery collapses. Bounded — identities live on
/// the agents, and old ids never legitimately repeat.
const _seenFrameIdsCap = 4096;

/// Per-request cap for whois/presence/welcome waits: a hub that never
/// answers must fail the request (which then falls back or retries), not
/// hang the caller.
const _replyTimeout = Duration(seconds: 10);

/// The DAP/1 hub as a [MessagingRepository].
final class HubMessagingRepository
    implements MessagingRepository, RoutingMessagingRepository {
  /// Builds a repository for the hub at [url]. [identity] defaults to a
  /// fresh one — hosts that need a stable address persist the seeds and
  /// pass them back (see `lib/io.dart`). [token] is the pairing token for
  /// a protected hub (rides the upgrade as `?dap_token=`, the browser-safe
  /// form). [onLog] receives soft diagnostics (decrypt failures, protocol
  /// errors) — never required.
  HubMessagingRepository({
    required Uri url,
    // ignore: prefer_initializing_formals
    required HubTransport transport,
    HubIdentity? identity,
    this.name,
    this.token,
    this.clientSecret,
    this.backoff = defaultHubBackoff,
    this.onLog,
  }) : _dialUrl = url,
       // ignore: prefer_initializing_formals
       _transport = transport,
       _identityFuture = identity == null
           ? HubIdentity.generate()
           : Future.value(identity);

  /// The dial URL (tokenless; the pairing token is folded in per dial).
  final Uri _dialUrl;
  final HubTransport _transport;
  final Future<HubIdentity> _identityFuture;

  /// The roster display name published by the signed hello — the session
  /// name (register refreshes it).
  String? name;

  /// The pairing token for a protected hub (write-only: never echoed).
  final String? token;

  /// Hub-issued enrollment credential (write-only: never echoed or logged).
  /// Requires a transport implementing [HubBearerTransport].
  final String? clientSecret;

  /// Reconnect backoff schedule (injectable: tests shrink it).
  final Duration Function(int attempt) backoff;

  /// Soft diagnostics sink (null = drop).
  void Function(String message)? onLog;

  HubIdentity? _identity;
  HubSocket? _socket;
  StreamSubscription<String>? _inbound;
  Timer? _reconnectTimer;
  bool _started = false;
  bool _disposed = false;
  int _attempt = 0;
  Completer<void>? _welcome;
  HubLinkState _state = HubLinkState.disconnected;
  final _stateChanges = StreamController<HubLinkState>.broadcast();

  /// Our hub address (the identity-derived id), set after the first
  /// welcome. Null until then.
  String? get agentId => _identity?.agentId;

  @override
  bool get isConnected => _state == HubLinkState.connected;

  /// The current link state (UI surface).
  HubLinkState get state => _state;

  /// Fires on every link-state transition.
  Stream<HubLinkState> get stateChanges => _stateChanges.stream;

  /// The capabilities announced by [register] (surfaced on our own
  /// directory entry until the hub wire carries them for peers).
  List<AgentCapability> capabilities = const [];

  /// True while the owner reported a run in progress ([touch]) — local
  /// presence knowledge; mail is accepted either way (steering semantics).
  bool busy = false;

  /// Our inbox: inbound DMs in arrival order.
  final _inbox = <AgentMessage>[];

  /// Recent inbound frame ids (dedup ring).
  final _seenFrameIds = <String>[];

  /// Messages queued while the link is down; drained in order on reconnect.
  final _outbound = <AgentMessage>[];

  /// Whois roster cache (agentId → peer), cleared on reconnect.
  final _whoisCache = <String, HubPeer>{};

  /// The roster as of the last successful presence query (the
  /// disconnected-directory view; null before the first contact).
  List<HubPeer>? _lastRoster;

  /// agentId → X25519 pubkey (b64) learned from whois answers.
  final _dhKeys = <String, String>{};

  final _pendingWhois = <String, List<Completer<HubPeer>>>{};
  final _pendingPresence = <String, Completer<List<HubPeer>>>{};

  /// Explicit channel memberships, restored after every reconnect. A null
  /// keypair is a PUBLIC channel: join keyless and use raw payloads (never
  /// mint a chankey).
  final _channels = <String, HubChannelKeys?>{};
  final _pendingJoins = <String, Completer<void>>{};
  final _joinOrder = <String>[];

  // ---------------------------------------------------------------------------
  // Lifecycle
  // ---------------------------------------------------------------------------

  /// Starts the connect loop: dials, handshakes, reconnects with backoff.
  /// Idempotent.
  Future<void> start() async {
    if (_started || _disposed) return;
    _started = true;
    _identity = await _identityFuture;
    _dial();
  }

  /// Waits for the current dial/reconnect loop to reach its first welcome.
  Future<void> waitForConnection({
    Duration timeout = const Duration(seconds: 10),
  }) async {
    if (isConnected) return;
    if (!_started || _disposed) {
      throw StateError('hub repository is not started');
    }
    await stateChanges
        .firstWhere((state) => state == HubLinkState.connected)
        .timeout(timeout);
  }

  /// Imports and joins [channel]. [keys] null means a keyless PUBLIC
  /// channel; no channel key is generated. Membership survives reconnects.
  Future<void> joinChannel(String channel, {HubChannelKeys? keys}) async {
    if (channel.isEmpty || channel.contains(RegExp(r'\s'))) {
      throw ArgumentError('invalid channel id');
    }
    _channels[channel] = keys;
    await waitForConnection();
    final pending = _pendingJoins[channel];
    if (pending != null) return pending.future;
    final joined = Completer<void>();
    _pendingJoins[channel] = joined;
    _joinOrder
      ..remove(channel)
      ..add(channel);
    try {
      await _sendJoin(channel);
      await joined.future.timeout(_replyTimeout);
    } on Object {
      if (_pendingJoins[channel] == joined) {
        _pendingJoins.remove(channel);
        _joinOrder.remove(channel);
      }
      rethrow;
    }
  }

  /// Stops the loop and closes the socket cleanly (the iOS background
  /// path: suspend → stop, foreground → start — reconnect + flush).
  Future<void> stop() async {
    _started = false;
    _reconnectTimer?.cancel();
    _reconnectTimer = null;
    await _dropSocket();
    _setState(HubLinkState.disconnected);
  }

  /// Permanent shutdown (the host is going away).
  Future<void> dispose() async {
    _disposed = true;
    await stop();
    await _stateChanges.close();
  }

  void _log(String message) => onLog?.call(message);

  void _setState(HubLinkState next) {
    if (_disposed || _state == next) return;
    _state = next;
    if (!_stateChanges.isClosed) _stateChanges.add(next);
  }

  void _dial() {
    if (!_started || _disposed) return;
    _setState(HubLinkState.connecting);
    unawaited(_dialOnce());
  }

  Future<void> _dialOnce() async {
    if (!_started || _disposed) return;
    final query = _dialUrl.queryParameters;
    final url = token == null || token!.isEmpty
        ? _dialUrl
        : _dialUrl.replace(queryParameters: {...query, 'dap_token': token});
    final HubSocket socket;
    try {
      socket = await _connectSocket(url);
    } on Object catch (error) {
      // An authenticated dial never stringifies the transport error: a
      // hostile/rejecting server must not be able to echo the credential
      // into host logs.
      _log(
        clientSecret == null
            ? 'hub connect failed: $error'
            : 'authenticated hub connect failed',
      );
      _scheduleReconnect();
      return;
    }
    _socket = socket;
    _whoisCache.clear();
    _dhKeys.clear();
    _inbound = socket.messages.cast<String>().listen(
      _onFrame,
      onDone: _onLinkDown,
      onError: (Object _) => _onLinkDown,
      cancelOnError: true,
    );
    final welcomed = _welcome = Completer<void>();
    try {
      await _sendHello();
      await welcomed.future.timeout(_replyTimeout);
    } on Object catch (error) {
      _log(
        clientSecret == null
            ? 'hub handshake failed: $error'
            : 'authenticated hub handshake failed',
      );
      await _dropSocket();
      _scheduleReconnect();
      return;
    }
    // Welcomed: live. Restore channel memberships, reset the backoff and
    // drain the offline mailbox plus everything queued while disconnected.
    _attempt = 0;
    _setState(HubLinkState.connected);
    // Rejoin BEFORE draining queued channel sends; otherwise a reconnect
    // could race send(not_joined) ahead of its membership restoration.
    await _restoreChannels();
    if (!identical(_socket, socket) || !isConnected) return;
    unawaited(_sendNow({'op': 'flush'}).catchError((Object _) {}));
    await _drainOutbound();
  }

  Future<HubSocket> _connectSocket(Uri url) {
    final secret = [REDACTED:Sensitive Value];
    if (secret == null || secret.isEmpty) {
      return _transport.connect(url);
    }
    final transport = _transport;
    if (transport is! HubBearerTransport) {
      throw StateError('hub transport has no bearer-auth capability');
    }
    return (transport as HubBearerTransport).connectWithBearer(url, secret);
  }

  Future<void> _sendHello() async {
    final identity = _identity;
    if (identity == null) throw StateError('identity not loaded');
    final frame = <String, dynamic>{
      'op': 'hello',
      'pubkey': identity.signingPubkeyB64,
      'x25519': identity.dhPubkeyB64,
      if (name != null && name!.isNotEmpty) 'name': name,
      'ts': DateTime.now().millisecondsSinceEpoch,
      'nonce': hubRandomHex(24),
    };
    frame['sig'] = await hubSignFrame(frame, identity);
    await _sendNow(frame);
  }

  void _scheduleReconnect() {
    if (!_started || _disposed) return;
    _setState(HubLinkState.disconnected);
    _attempt += 1;
    _reconnectTimer?.cancel();
    // A zero backoff between dial failures would spin a tight loop on a
    // refused port — floor the schedule at one tick.
    final delay = backoff(_attempt);
    _reconnectTimer = Timer(
      delay == Duration.zero ? const Duration(milliseconds: 1) : delay,
      _dial,
    );
  }

  Future<void> _dropSocket() async {
    _inbound?.cancel();
    _inbound = null;
    final socket = _socket;
    _socket = null;
    _failWaiters('hub link down');
    try {
      await socket?.close();
    } on Object {
      // Already gone.
    }
  }

  void _onLinkDown() {
    _inbound = null;
    _socket = null;
    _failWaiters('hub link down');
    _scheduleReconnect();
  }

  void _failWaiters(String error) {
    for (final waiters in _pendingWhois.values) {
      for (final waiter in waiters) {
        if (!waiter.isCompleted) waiter.completeError(StateError(error));
      }
    }
    _pendingWhois.clear();
    for (final waiter in _pendingPresence.values) {
      if (!waiter.isCompleted) waiter.completeError(StateError(error));
    }
    _pendingPresence.clear();
    for (final waiter in _pendingJoins.values) {
      if (!waiter.isCompleted) waiter.completeError(StateError(error));
    }
    _pendingJoins.clear();
    _joinOrder.clear();
    final welcome = _welcome;
    if (welcome != null && !welcome.isCompleted) {
      welcome.completeError(StateError(error));
    }
    _welcome = null;
  }

  // ---------------------------------------------------------------------------
  // Inbound frames
  // ---------------------------------------------------------------------------

  void _onFrame(String text) {
    Map<String, dynamic> frame;
    try {
      frame = (jsonDecode(text) as Map).cast<String, dynamic>();
    } on Object {
      _log('hub sent a non-JSON frame');
      return;
    }
    switch (frame['op'] as String?) {
      case 'welcome':
        _onWelcome();
      case 'msg':
        unawaited(_onMsg(frame));
      case 'agent_info':
        _onAgentInfo(frame);
      case 'presence':
        _onPresence(frame);
      case 'flushed':
        break; // queued mail already arrived as msg frames
      case 'joined':
        _onJoined(frame);
      case 'error':
        _onErrorFrame(frame);
      default:
        break;
    }
  }

  void _onWelcome() {
    final welcome = _welcome;
    if (welcome != null && !welcome.isCompleted) {
      welcome.complete();
      _welcome = null;
    }
  }

  void _onJoined(Map<String, dynamic> frame) {
    final channel = frame['channel'] as String? ?? '';
    _joinOrder.remove(channel);
    final waiter = _pendingJoins.remove(channel);
    if (waiter != null && !waiter.isCompleted) waiter.complete();
  }

  void _onErrorFrame(Map<String, dynamic> frame) {
    final code = frame['code'] as String? ?? 'unknown';
    if (code == 'access_denied' && _joinOrder.isNotEmpty) {
      final channel = _joinOrder.removeAt(0);
      final waiter = _pendingJoins.remove(channel);
      if (waiter != null && !waiter.isCompleted) {
        waiter.completeError(StateError('hub denied channel join'));
      }
    }
    _log(
      clientSecret == null
          ? 'hub error: $code ${frame['msg']}'
          : 'authenticated hub error: $code',
    );
  }

  Future<void> _onMsg(Map<String, dynamic> frame) async {
    final id = frame['id'] as String? ?? '';
    if (id.isEmpty || _identity == null) return;
    if (_seenFrameIds.contains(id)) return; // dedup by id (at-least-once)
    _seenFrameIds.add(id);
    if (_seenFrameIds.length > _seenFrameIdsCap) _seenFrameIds.removeAt(0);
    final from = frame['from'] as String? ?? '';
    final channel = frame['channel'] as String?;
    if (channel != null) {
      await _onChannelMsg(frame, id, channel, from);
      return;
    }
    String text;
    try {
      var dhB64 = _dhKeys[from];
      if (dhB64 == null) {
        // The sender's DH key arrives with whois; resolve, then decrypt.
        await _whois(from);
        dhB64 = _dhKeys[from];
      }
      if (dhB64 == null) throw StateError('no DH key for $from');
      text = await hubDecryptPayload(
        ourIdentity: _identity!,
        senderDhPubkey: SimplePublicKey(
          base64Decode(dhB64),
          type: KeyPairType.x25519,
        ),
        frameId: id,
        ciphertextB64: frame['ciphertext'] as String? ?? '',
      );
    } on Object catch (error) {
      // Undecryptable (unknown sender key, tampered payload): never deliver
      // opaque ciphertext into the chat — drop with a diagnostic.
      _log('dropped undecryptable DM from $from: $error');
      return;
    }
    _inbox.add(
      AgentMessage(
        id: id,
        fromId: from,
        toId: agentId ?? '',
        text: text,
        sentAt: DateTime.fromMillisecondsSinceEpoch(
          frame['ts'] as int? ?? 0,
        ).toUtc().toIso8601String(),
      ),
    );
  }

  Future<void> _onChannelMsg(
    Map<String, dynamic> frame,
    String id,
    String channel,
    String from,
  ) async {
    // Some hubs fan out to the sender too; own channel echo is not new
    // steering (the local transcript already has the tool result).
    if (from == agentId || !_channels.containsKey(channel)) return;
    final keys = _channels[channel];
    String text;
    try {
      if (keys == null) {
        text = _decodePublicChannelPayload(
          frame['ciphertext'] as String? ?? '',
        );
      } else {
        var dhB64 = _dhKeys[from];
        if (dhB64 == null) {
          await _whois(from);
          dhB64 = _dhKeys[from];
        }
        if (dhB64 == null) throw StateError('no sender DH key');
        final channelPub = SimplePublicKey(
          base64Decode(keys.pub),
          type: KeyPairType.x25519,
        );
        text = await hubDecryptPayloadWithKeyPair(
          recipientDhKeyPair: SimpleKeyPairData(
            base64Decode(keys.priv),
            publicKey: channelPub,
            type: KeyPairType.x25519,
          ),
          senderDhPubkey: SimplePublicKey(
            base64Decode(dhB64),
            type: KeyPairType.x25519,
          ),
          frameId: id,
          aadTarget: channel,
          ciphertextB64: frame['ciphertext'] as String? ?? '',
        );
      }
    } on Object {
      // Never print the error here: base64 parsers can echo their input,
      // which is invite key material on this path.
      _log('dropped undecryptable channel mail from $from');
      return;
    }
    _inbox.add(
      AgentMessage(
        id: id,
        fromId: from,
        toId: '#$channel',
        text: text,
        sentAt: DateTime.fromMillisecondsSinceEpoch(
          frame['ts'] as int? ?? 0,
        ).toUtc().toIso8601String(),
      ),
    );
  }

  void _onAgentInfo(Map<String, dynamic> frame) {
    final agentId = frame['agentId'] as String? ?? '';
    final peer = HubPeer(
      agentId: agentId,
      name: frame['name'] as String?,
      online: frame['online'] as bool? ?? false,
    );
    _whoisCache[agentId] = peer;
    final dh = frame['x25519'] as String?;
    if (dh != null && dh.isNotEmpty) _dhKeys[agentId] = dh;
    final waiters = _pendingWhois.remove(agentId);
    if (waiters == null) return;
    for (final waiter in waiters) {
      if (!waiter.isCompleted) waiter.complete(peer);
    }
  }

  void _onPresence(Map<String, dynamic> frame) {
    final replyTo = frame['replyTo'] as String?;
    final agents = [
      for (final entry in (frame['agents'] as List? ?? const []))
        if (entry is Map)
          HubPeer(
            agentId: entry['agentId'] as String? ?? '',
            name: entry['name'] as String?,
            online: entry['online'] as bool? ?? false,
          ),
    ];
    if (replyTo != null) {
      final waiter = _pendingPresence.remove(replyTo);
      if (waiter != null && !waiter.isCompleted) {
        waiter.complete(agents);
        return;
      }
    }
    // Legacy hub (no replyTo echo): complete the oldest waiter.
    if (_pendingPresence.isNotEmpty) {
      final waiter = _pendingPresence.remove(_pendingPresence.keys.first)!;
      if (!waiter.isCompleted) waiter.complete(agents);
    }
  }

  /// Whois with caching — the spec-required lookup before a DM.
  Future<HubPeer> _whois(String agentId) async {
    if (agentId.isEmpty) throw ArgumentError('whois needs an agent id');
    final cached = _whoisCache[agentId];
    if (cached != null) return cached;
    final waiter = Completer<HubPeer>();
    _pendingWhois.putIfAbsent(agentId, () => []).add(waiter);
    await _sendNow({'op': 'whois', 'agentId': agentId});
    final peer = await waiter.future.timeout(_replyTimeout);
    _whoisCache[agentId] = peer;
    return peer;
  }

  Future<List<HubPeer>> _presenceQuery() async {
    if (!isConnected) throw StateError('hub link is not connected');
    final id = newHubFrameId();
    final waiter = Completer<List<HubPeer>>();
    _pendingPresence[id] = waiter;
    await _sendNow({'op': 'presence_query', 'id': id});
    try {
      return await waiter.future.timeout(_replyTimeout);
    } on Object {
      _pendingPresence.remove(id);
      rethrow;
    }
  }

  // ---------------------------------------------------------------------------
  // RoutingMessagingRepository
  // ---------------------------------------------------------------------------

  @override
  Future<String?> resolveTarget(String toId) async {
    if (!isConnected) return null;
    if (toId.startsWith('#')) {
      final channel = toId.substring(1);
      return _channels.containsKey(channel) ? toId : null;
    }
    final me = agentId;
    if (me != null && toId == me) return null; // our own fabric mailbox
    final roster = await _presenceQuery();
    for (final peer in roster) {
      if (peer.agentId == toId) return toId; // exact id wins
    }
    final byName = roster
        .where((peer) => peer.name == toId && peer.agentId != me)
        .toList();
    // A display name resolves only when it is unambiguous — matches the
    // dap_dm resolver; anything else falls through to the file fabric.
    return byName.length == 1 ? byName.single.agentId : null;
  }

  // ---------------------------------------------------------------------------
  // MessagingRepository
  // ---------------------------------------------------------------------------

  @override
  Future<void> send(AgentMessage message) async {
    if (!isConnected) {
      // Queue-while-disconnected: the message keeps its id and position;
      // the reconnect drain preserves per-sender order.
      _outbound.add(message);
      return;
    }
    // A mid-flight failure (whois race, evicted socket) rethrows: the
    // composition falls back to the file fabric and tracks the message for
    // forward-on-reconnect; a standalone caller sees the throw (the
    // contract: never lose mail silently).
    await _sendLive(message);
  }

  Future<void> _sendLive(AgentMessage message) async {
    final identity = _identity;
    if (identity == null) throw StateError('hub fabric not welcomed yet');
    final to = message.toId;
    if (to.startsWith('#')) {
      await _sendChannelLive(identity, message, to.substring(1));
      return;
    }
    var dhB64 = _dhKeys[to];
    if (dhB64 == null) {
      // Spec: whois before the first DM.
      await _whois(to);
      dhB64 = _dhKeys[to];
    }
    if (dhB64 == null) {
      throw StateError('hub returned no x25519 pubkey for "$to"');
    }
    final id = message.id.isEmpty ? newHubFrameId() : message.id;
    final ciphertext = await hubEncryptPayload(
      sender: identity,
      recipientDhPubkey: SimplePublicKey(
        base64Decode(dhB64),
        type: KeyPairType.x25519,
      ),
      frameId: id,
      aadTarget: to,
      plaintext: message.text,
    );
    final frame = <String, dynamic>{
      'op': 'send',
      'to': to,
      'id': id,
      'ts': DateTime.now().millisecondsSinceEpoch,
      'ciphertext': ciphertext,
    };
    frame['sig'] = await hubSignFrame(frame, identity);
    await _sendNow(frame);
  }

  Future<void> _sendChannelLive(
    HubIdentity identity,
    AgentMessage message,
    String channel,
  ) async {
    if (!_channels.containsKey(channel)) {
      throw StateError('not a member of #$channel');
    }
    final keys = _channels[channel];
    final id = message.id.isEmpty ? newHubFrameId() : message.id;
    final ciphertext = keys == null
        ? base64Encode(utf8.encode(jsonEncode({'text': message.text})))
        : await hubEncryptPayload(
            sender: identity,
            recipientDhPubkey: SimplePublicKey(
              base64Decode(keys.pub),
              type: KeyPairType.x25519,
            ),
            frameId: id,
            aadTarget: channel,
            plaintext: message.text,
          );
    final frame = <String, dynamic>{
      'op': 'send',
      'channel': channel,
      'id': id,
      'ts': DateTime.now().millisecondsSinceEpoch,
      'ciphertext': ciphertext,
    };
    frame['sig'] = await hubSignFrame(frame, identity);
    await _sendNow(frame);
  }

  /// Drains the offline queue in order after a welcome. A mid-drain failure
  /// keeps the remainder queued (front of the queue, order intact) for the
  /// next reconnect cycle.
  Future<void> _drainOutbound() async {
    while (_outbound.isNotEmpty && isConnected) {
      final message = _outbound.first;
      try {
        await _sendLive(message);
        _outbound.removeAt(0);
      } on Object {
        _log('outbound drain deferred (${_outbound.length} queued)');
        return;
      }
    }
  }

  @override
  Future<void> register(
    String agentId, {
    String? sessionName,
    List<AgentCapability> capabilities = const [],
  }) async {
    if (sessionName != null && sessionName.isNotEmpty) name = sessionName;
    this.capabilities = capabilities;
    // Presence rides the signed hello; a live name change re-announces on
    // the spot (best-effort — a failed announce never breaks startup).
    if (isConnected) {
      try {
        await _sendHello();
      } on Object catch (error) {
        _log('hello re-announce failed: $error');
      }
    }
  }

  @override
  Future<void> touch(String agentId, {bool busy = false}) async {
    // Hub liveness is the connection itself; the busy run-state is local
    // knowledge (surfaced on our own directory entry) until the hub wire
    // carries presence states (phase 27.2).
    this.busy = busy;
  }

  @override
  Future<List<AgentMessage>> peek(String agent) =>
      Future.value(List.of(_inbox));

  @override
  Future<List<AgentMessage>> drain(String agent) async {
    final drained = List.of(_inbox);
    _inbox.clear();
    return drained;
  }

  @override
  Future<List<MailboxEntry>> directory() async {
    final me = agentId;
    List<HubPeer> roster;
    try {
      roster = await _presenceQuery();
      _lastRoster = roster;
    } on Object {
      // Link down: the roster as of last contact, everyone offline — the
      // honest disconnected view (a UI shows the network unreachable, not
      // a stale guess at who is live). Never connected → nothing to show.
      final last = _lastRoster;
      if (last == null) rethrow;
      roster = [
        for (final peer in last)
          HubPeer(agentId: peer.agentId, name: peer.name, online: false),
      ];
    }
    return [
      for (final peer in roster)
        MailboxEntry(
          id: peer.agentId,
          name: peer.name,
          // Registration-backed presence: the hub knows who is connected —
          // no mtime heuristic. Our own busy run-state rides on top.
          presence: peer.agentId == me && busy
              ? AgentPresence.busy
              : peer.online
              ? AgentPresence.live
              : AgentPresence.offline,
          capabilities: peer.agentId == me ? capabilities : const [],
          source: mailboxSourceHub,
        ),
    ];
  }

  // ---------------------------------------------------------------------------
  // Wire
  // ---------------------------------------------------------------------------

  Future<void> _restoreChannels() async {
    for (final channel in _channels.keys.toList()) {
      if (!isConnected) return;
      try {
        await joinChannel(channel, keys: _channels[channel]);
      } on Object {
        _log('channel join deferred for #$channel');
      }
    }
  }

  Future<void> _sendJoin(String channel) => _sendNow({
    'op': 'join',
    'channel': channel,
    'chanPubkey': _channels[channel]?.pub ?? '',
  });

  Future<void> _sendNow(Map<String, dynamic> frame) async {
    final socket = _socket;
    if (socket == null || !socket.isOpen) {
      throw StateError('hub link is not open');
    }
    await socket.send(jsonEncode(frame));
  }
}

/// PUBLIC showcase payload: base64(JSON text), with raw UTF-8 tolerated
/// for foreign producers. Invalid bytes throw and are dropped by the
/// caller; nothing is downgraded for keyed channels.
String _decodePublicChannelPayload(String payloadB64) {
  final raw = utf8.decode(base64Decode(payloadB64));
  try {
    final decoded = jsonDecode(raw);
    if (decoded is Map && decoded['text'] is String) {
      return decoded['text'] as String;
    }
  } on Object {
    // Raw UTF-8 from a foreign producer.
  }
  return raw;
}

