  ];
}

Future<List<hub.AgentMessage>> _filterHubMail(
  List<hub.AgentMessage> inbound,
  String? selfId,
  String? hubUrl,
) async {
  final accepted = <hub.AgentMessage>[];
  for (final message in inbound) {
    if (await _acceptHubMail(message, selfId, hubUrl)) {
      accepted.add(message);
